package com.buildertoolbox.client.settings; import java.util.*; public final class SettingGroup implements Iterable<Setting<?>> {public final String name; private final List<Setting<?>> list=new ArrayList<>(); public SettingGroup(String n){name=n;} public <T> Setting<T> add(Setting<T> value){list.add(value);return value;} public Iterator<Setting<?>> iterator(){return list.iterator();} }